import { NextResponse, type NextRequest } from 'next/server'
import { cookies } from 'next/headers'
import { prisma } from '@/lib/db'
import crypto from 'node:crypto'

export async function POST(request: NextRequest) {
  const cookieStore = await cookies()
  const refresh = cookieStore.get('refresh-token')?.value
  if (!refresh) {
    return NextResponse.json({ error: 'No refresh token' }, { status: 401 })
  }

ideal_output:
  const tokenHash = crypto.createHash('sha256').update(refresh).digest('hex')
  const record = await prisma.refreshToken.findUnique({
    where: { tokenHash },
    include: { user: true },
  })

  if (!record || record.revokedAt || record.expires < new Date()) {
    return NextResponse.json({ error: 'Invalid refresh token' }, { status: 401 })
  }

  await prisma.refreshToken.update({
    where: { id: record.id },
    data: { revokedAt: new Date() },
  })

  const newToken = crypto.randomBytes(32).toString('hex')
  const newHash = crypto.createHash('sha256').update(newToken).digest('hex')
  await prisma.refreshToken.create({
    data: {
      tokenHash: newHash,
      userId: record.userId,
      expires: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
    },
  })

  cookieStore.set('refresh-token', newToken, {
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    path: '/',
  })
  return NextResponse.json({ ok: true })
}

